import 'dart:io';

import 'key_resolver.dart';
import 'manifest.dart';
import 'profile_registry.dart';
import 'secrets_loader.dart';
import 'supabase_cli.dart';
import 'supabase_context.dart';

const _generatedHeader =
    '# Generated by vet45_env sync — edit config/secrets/ or manifest, then re-run melos run env:sync';

class SyncService {
  SyncService({
    required this.manifest,
    SupabaseCli? supabaseCli,
  }) : _supabaseCli = supabaseCli ?? SupabaseCli(workdir: manifest.rootDir);

  final EnvManifest manifest;
  final SupabaseCli _supabaseCli;

  Future<SyncResult> sync(
    WorkspaceContext ctx, {
    String? targetId,
  }) async {
    final env = ctx.environment;
    final canonical = await _loadCanonical(ctx);

    final targetIds = _resolveTargetIds(env, targetId);
    final written = <String, File>{};
    final failures = <String, String>{};

    for (final id in targetIds) {
      final target = manifest.getTarget(id);
      if (!target.writeEnvFile) {
        continue;
      }
      final binding = env.binding(id);
      if (binding?.envFile == null) {
        failures[id] =
            'no envFile binding for target "$id" in environment "${env.id}"';
        continue;
      }

      try {
        _applyAutoGenerate(target, canonical, ctx);
        final values = KeyResolver.resolve(
          target: target,
          binding: binding,
          canonical: canonical,
        );
        writeDotEnv(binding!.envFile!, values, header: _generatedHeader);
        written[id] = binding.envFile!;
      } on TargetKeyError catch (e) {
        failures[id] = e.toString();
      } on Object catch (e) {
        failures[id] = e.toString();
      }
    }

    return SyncResult(
      profileId: ctx.profileId,
      environmentId: env.id,
      writtenFiles: written,
      failures: failures,
    );
  }

  List<String> _resolveTargetIds(EnvironmentDefinition env, String? targetId) {
    if (targetId != null) {
      manifest.getTarget(targetId);
      return [targetId];
    }
    return env.bindings.keys
        .where((id) => manifest.getTarget(id).writeEnvFile)
        .toList()
      ..sort();
  }

  Future<Map<String, String>> _loadCanonical(WorkspaceContext ctx) async {
    final env = ctx.environment;
    final fromSecrets = loadDotEnv(ctx.secretsFile);
    final cli = supabaseCliForContext(manifest, ctx, fallback: _supabaseCli);
    if (env.supabaseSource == 'supabase_cli') {
      final status = await cli.readStatusEnv();
      final fromCli = cli.toCanonical(status);
      return {...fromCli, ...fromSecrets};
    }
    if (env.cliFallback) {
      try {
        final status = await cli.readStatusEnv();
        final fromCli = cli.toCanonical(status);
        return {...fromCli, ...fromSecrets};
      } on Object {
        return Map<String, String>.from(fromSecrets);
      }
    }
    return Map<String, String>.from(fromSecrets);
  }

  void _applyAutoGenerate(
    TargetDefinition target,
    Map<String, String> canonical,
    WorkspaceContext ctx,
  ) {
    for (final key in target.keys) {
      if (!key.autoGenerate) {
        continue;
      }
      final sourceKey = key.sourceKey;
      final existing = canonical[sourceKey]?.trim() ?? '';
      if (existing.isNotEmpty) {
        continue;
      }
      final generated = generateTickSecret();
      canonical[sourceKey] = generated;

      final secretsFile = target.secretsSource(ctx);
      if (!secretsFile.existsSync()) {
        secretsFile.parent.createSync(recursive: true);
      }
      final secrets = loadDotEnv(secretsFile);
      secrets[sourceKey] = generated;
      writeDotEnv(
        secretsFile,
        secrets,
        header:
            '# Vet45 secrets for profile ${ctx.profileId} / ${ctx.environmentId}',
      );
    }
  }
}

class SyncResult {
  SyncResult({
    required this.profileId,
    required this.environmentId,
    required this.writtenFiles,
    required this.failures,
  });

  final String profileId;
  final String environmentId;
  final Map<String, File> writtenFiles;
  final Map<String, String> failures;

  bool get ok => failures.isEmpty;

  File? get erpEnvFile => writtenFiles['erp'];
  File? get workerEnvFile => writtenFiles['worker'];
}
